class DragwybRangeSlider extends DragwybBuilder.DragwybFormFrontendBase{bindElements(){this.elements.$form=this.$container.is("form")?this.$container:this.$container.find("form.dragwyb-form")}init(){const $sliders=this.$container.find(".dragwyb-custom-range-container");$sliders.each((_,el)=>{this.initSlider(jQuery(el))})}initSlider($slider){const $input=$slider.find('input[type="range"]'),$progress=$slider.find(".dragwyb-range-progress"),$thumb=$slider.find(".dragwyb-range-thumb");if(!$input.length)return;const updateVisuals=()=>{const min=parseFloat($input.attr("min"))||0,max=parseFloat($input.attr("max"))||100,val=parseFloat($input.val())||0;let percentage=(val-min)/(max-min)*100;percentage<0&&(percentage=0),percentage>100&&(percentage=100),$progress.css("width",`${percentage}%`),$thumb.css("left",`${percentage}%`)};updateVisuals(),$input.on("input",()=>{updateVisuals()}),$input.on("focus",()=>{$slider.addClass("dragwyb-range-focused")}).on("blur",()=>{$slider.removeClass("dragwyb-range-focused")})}}jQuery(document).on("Dragwyb:frontendInit",()=>{DragwybBuilder.Hooks.addAction("dragwyb/frontend/form_ready",(container,formId)=>{new DragwybRangeSlider(container)})}),jQuery(document).on("Dragwyb:editorAppLoaded",()=>{DragwybBuilder.Hooks.addAction("dragwyb/editorPreview/form_ready",(container,formId)=>{new DragwybRangeSlider(container)})});